{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    payload = case.get("payload")
    if payload is None:
        raise ValueError("Missing payload")

    nodes = payload.get("nodes")
    required_symbols = payload.get("required_symbols")

    if nodes is None:
        raise ValueError("Missing nodes")
    if required_symbols is None:
        raise ValueError("Missing required_symbols")
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")

    required_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    for node in nodes:
        missing = required_fields - set(node.keys())
        if missing:
            raise ValueError(f"Node missing fields: {missing}")

    node_map = {}
    for node in nodes:
        nid = node["id"]
        if nid in node_map:
            raise ValueError(f"Duplicate node id: {nid}")
        node_map[nid] = node

    children = {nid: [] for nid in node_map}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in node_map:
                raise ValueError(f"Parent '{parent}' not found for node '{node['id']}'")
            children[parent].append(node["id"])

    all_symbols = {n["symbol"] for n in nodes}
    for sym in required_symbols:
        if sym not in all_symbols:
            raise ValueError(f"Required symbol '{sym}' not present in any node")

    # Sort: depth descending, then node ID ascending as stable tie-break
    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    retained = set(node_map.keys())
    removal_order = []

    for node in candidates:
        nid = node["id"]

        if not node["removable"]:
            continue

        # Cannot remove if any direct child is still retained
        if any(child in retained for child in children[nid]):
            continue

        # Tentatively remove: check all required symbols remain represented
        retained_after = retained - {nid}
        remaining_symbols = {node_map[rid]["symbol"] for rid in retained_after}
        if all(sym in remaining_symbols for sym in required_symbols):
            retained.discard(nid)
            removal_order.append(nid)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order
    }
